package com.hotel.service.impl;
import com.hotel.dao.CustomerDao; import com.hotel.dto.*; import com.hotel.exception.ValidationException; import org.junit.jupiter.api.*; import java.time.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class CustomerServiceImplTest {CustomerDao dao;CustomerServiceImpl service;@BeforeEach void setup(){dao=mock(CustomerDao.class);service=new CustomerServiceImpl(dao);}private CustomerFormDto valid(){return new CustomerFormDto(null,"Guest Name","guest@example.com","123",LocalDate.of(2000,1,1),"PASSPORT","P1","VN","Address",null);}@Test void rejectsBlankName(){var f=new CustomerFormDto(null," ",null,null,null,null,null,null,null,null);assertThrows(ValidationException.class,()->service.create(f,7));verifyNoInteractions(dao);}@Test void rejectsInvalidEmail(){var x=valid();var f=new CustomerFormDto(null,x.fullName(),"bad",x.phone(),x.dateOfBirth(),x.idDocumentType(),x.idDocumentNumber(),x.nationality(),x.address(),null);assertThrows(ValidationException.class,()->service.create(f,7));}@Test void rejectsFutureBirthDate(){var x=valid();var f=new CustomerFormDto(null,x.fullName(),x.email(),x.phone(),LocalDate.now().plusDays(1),x.idDocumentType(),x.idDocumentNumber(),x.nationality(),x.address(),null);assertThrows(ValidationException.class,()->service.create(f,7));}@Test void requiresBothDocumentFields(){var x=valid();var f=new CustomerFormDto(null,x.fullName(),x.email(),x.phone(),x.dateOfBirth(),x.idDocumentType(),null,x.nationality(),x.address(),null);assertThrows(ValidationException.class,()->service.create(f,7));}@Test void rejectsDuplicateDocument(){when(dao.documentExists("PASSPORT","P1",null)).thenReturn(true);assertThrows(ValidationException.class,()->service.create(valid(),7));}@Test void creatorComesFromServiceArgumentAndWalkInCodeIsGenerated()throws Exception{when(dao.create(any(),eq(42L),startsWith("WI-"))).thenReturn(9L);assertEquals(9,service.create(valid(),42));verify(dao).create(argThat(f->f.id()==null),eq(42L),startsWith("WI-"));}@Test void normalizesSearchPaging(){var c=new CustomerSearchCriteria("  Jane   Doe ",null,0,20);assertEquals("Jane Doe",c.keyword());assertEquals(1,c.page());}@Test void detectsMissingCustomerOnUpdate(){var f=new CustomerFormDto(99L,"Name",null,null,null,null,null,null,null,LocalDateTime.now());when(dao.findDetail(99)).thenReturn(Optional.empty());assertThrows(ValidationException.class,()->service.update(f));}@Test void excludesCurrentCustomerFromDuplicateCheck()throws Exception{var f=new CustomerFormDto(3L,"Name",null,null,null,"ID","X",null,null,LocalDateTime.now());when(dao.findDetail(3)).thenReturn(Optional.of(mock(CustomerDetailDto.class)));when(dao.update(f)).thenReturn(true);service.update(f);verify(dao).documentExists("ID","X",3L);}}
